// "Recorded" style: you talking to the camera (real footage), assembled from two files of the job:
//   recording/edl.json — generated by scripts/recording.py (segments of the cut and words timed on the cut)
//   edit.json          — written by hand/by Claude: what happens on each word (see .claude/skills/recorded)
// Every time reference is a WORD INDEX of edl.json: the effect lands on the syllable, not on a guess.
import { SIZE } from "../components/formats";
import type { FormatWithLandscape } from "../components/formats";
import type { Theme as BrandTheme } from "../components/theme";

export type EdlWord = { i: number; src_i?: number; text: string; start: number; end: number };
// start/end = seconds in the cut video; src_start/src_end = seconds in the original recording
export type Segment = { start: number; end: number; src_start: number; src_end: number };
export type Edl = { fps: number; duration: number; factor?: number; segments: Segment[]; words: EdlWord[] };

export type Format = FormatWithLandscape;
export const DIMENSIONS: Record<Format, [number, number]> = SIZE;

export type Theme = {
  dark: string; // background of the dark panels
  paper: string; // light "canvas" background (keynote style)
  ink: string; // text on paper
  light: string; // text on dark/video
  accent: string; // ONE highlight color
  sans: "inter" | "geist" | "instrument-sans";
  serif: "instrument-serif" | "newsreader";
  mono: "jetbrains" | "geist-mono" | "plex";
};

// What goes inside a panel: a file (image/video) or a graphic drawn in Remotion.
export type Media =
  | string // file of <job>/media/ (scripts/prepare.py copies it to public/<slug>/): "repo.png", "broll.mp4"
  | { screenshot: string; zoom?: [number, number]; focus?: string; frame?: boolean } // screen/site capture with frame and slow zoom
  | { diagram: { root: string; items: { text: string; word: number; icon?: string; sub?: string }[]; done?: number } }
  | { steps: { items: { text: string; word: number }[]; center?: string } } // 1–2–3 with dashed lines (long video)
  | { canvas: { items: { img: string; label?: string; word: number }[]; title?: { text: string; word: number } } }
  | { list: { title?: string; items: { text: string; word: number; ok?: boolean }[] } }
  // app screen in a phone (id registered in components/screens; props = the screen's own props)
  | { ui: string; props?: Record<string, unknown> };

export type Block =
  // split screen: you in one half, the media in the other (9:16 → media on top; 16:9 → media on the right)
  | { type: "split"; from: number; to: number; media: Media; side?: "top" | "bottom" | "left" | "right"; background?: "dark" | "paper"; label?: string }
  // full-screen media (b-roll, screenshot, canvas); your voice keeps going underneath
  | { type: "full"; from: number; to: number; media: Media; background?: "dark" | "paper"; label?: string }
  // big text; *word* between asterisks comes out in the accent color
  | { type: "title"; word: number; text: string; seconds?: number; font?: "serif" | "sans" | "mono"; position?: "top" | "center" | "bottom"; size?: number }
  // chapter card (long video): number + title over the darkened media
  | { type: "chapter"; word: number; number: number | string; title: string; media?: Media; seconds?: number; label?: string };

export type Edit = {
  theme?: Partial<Theme>;
  brand?: Partial<BrandTheme>; // brand colors for app screens (`ui` media) and the branded end card (components/theme.ts)
  captions?: {
    // impact: 1–2 big uppercase words, the spoken one lights up in the accent with a pop (fast-paced ad)
    style?: "editorial" | "mono" | "minimal" | "impact" | "none";
    max?: number; // words at a time
    highlights?: number[]; // word indices shown in the accent color
    hide?: [number, number][]; // word ranges without captions (e.g. covered by a title)
    size?: number;
  };
  camera?: { alternate?: [number, number]; push?: number; focus?: string };
  punches?: { word: number; zoom?: number }[];
  // dynamic version (ad): zoom jolt on each cut, punch with shake on every caption highlight, camera pulsing on the
  // music beats, panels and titles entering with a pop instead of blur
  rhythm?: { beats?: string; pulse?: number; snap?: number; autoPunches?: boolean };
  blocks?: Block[];
  music?: { file: string; volume?: number; start?: number };
  sfx?: boolean | { whoosh?: number; pop?: number }; // whoosh/pop on entrances (library/sfx); object = volumes
  // branded: CTA in the brand identity (components/EndCard, logo.svg of the job, theme.accent) instead of the paper card
  endCard?: { text: string; sub?: string; seconds?: number; branded?: boolean; cta?: string };
};

export const DEFAULT_THEME: Theme = {
  dark: "#0b0b0c",
  paper: "#f4f3ef",
  ink: "#111111",
  light: "#f5f5f4",
  accent: "#e4f75a",
  sans: "inter",
  serif: "instrument-serif",
  mono: "jetbrains",
};

// time (s) when the word starts / ends; an out-of-range index is clamped to the ends
export const wordStart = (edl: Edl, i: number) => edl.words[Math.max(0, Math.min(edl.words.length - 1, i))].start;
export const wordEnd = (edl: Edl, i: number) => edl.words[Math.max(0, Math.min(edl.words.length - 1, i))].end;
